using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using UnityEngine;using UnityEngine.Rendering;using SpatialWallpaper.Content;using SpatialWallpaper.Sdk.Native;
namespace SpatialWallpaper.Sdk.Editor {
 // The first external format deliberately exports a lossless static subset.
 // Unsupported author components are rejected before any export allocations.
 public static class ExternalNativeExporter {
  public static string Export(SceneDefinition definition,string outputPath,string revision="1.0.0"){
   if(!definition||!definition.contentRoot)throw new InvalidDataException("external:scene-definition");if(File.Exists(outputPath))throw new IOException("external:destination-exists");
   var program=CilboxProgramCompiler.CompileForNativeBridge(definition.contentRoot.gameObject);byte[] authorScript=new ExternalNativeAuthorMetadata(program,definition.contentRoot).Encode(definition.authorFrame);var transforms=definition.contentRoot.GetComponentsInChildren<Transform>(true);foreach(var t in transforms){
    if(!t.gameObject.activeSelf)throw new InvalidDataException("external:inactive-node-not-supported:"+t.name);
    foreach(var c in t.GetComponents<Component>())if(!c||!(c is Transform||c is MeshFilter||c is MeshRenderer||c is Light||c is MonoBehaviour&&program.Classes.ContainsKey(c.GetType().FullName)))throw new InvalidDataException("external:unsupported-component:"+(c?c.GetType().FullName:"missing-script"));
    var filter=t.GetComponent<MeshFilter>();var renderer=t.GetComponent<MeshRenderer>();if((bool)filter!=(bool)renderer)throw new InvalidDataException("external:mesh-renderer-pair");if(filter){var mesh=filter.sharedMesh;if(!mesh||mesh.blendShapeCount!=0||mesh.bindposes.Length!=0)throw new InvalidDataException("external:skinning-blendshape-not-supported");if(mesh.normals.Length!=mesh.vertexCount||mesh.tangents.Length!=mesh.vertexCount||mesh.uv.Length!=mesh.vertexCount||mesh.uv2.Length!=mesh.vertexCount||mesh.colors.Length!=mesh.vertexCount)throw new InvalidDataException("external:explicit-full-mesh-channels-required");if(mesh.GetVertexAttributeDimension(VertexAttribute.TexCoord0)!=2||mesh.GetVertexAttributeDimension(VertexAttribute.TexCoord1)!=2)throw new InvalidDataException("external:uv-dimension-not-supported");for(int submesh=0;submesh<mesh.subMeshCount;submesh++)if(mesh.GetTopology(submesh)!=MeshTopology.Triangles)throw new InvalidDataException("external:mesh-topology-not-supported");for(int channel=2;channel<8;channel++)if(mesh.HasVertexAttribute((VertexAttribute)((int)VertexAttribute.TexCoord0+channel)))throw new InvalidDataException("external:uv-channel-not-supported");if(renderer.shadowCastingMode!=ShadowCastingMode.On||!renderer.receiveShadows||renderer.lightProbeUsage!=LightProbeUsage.Off||renderer.reflectionProbeUsage!=ReflectionProbeUsage.Off||renderer.sortingLayerID!=0||renderer.sortingOrder!=0)throw new InvalidDataException("external:renderer-setting-not-represented");foreach(var mat in renderer.sharedMaterials){if(!mat)throw new InvalidDataException("external:missing-material");foreach(var name in mat.GetTexturePropertyNames()){var texture=mat.GetTexture(name);if(texture&&(!(texture is Texture2D)||((Texture2D)texture).format==TextureFormat.RGBAFloat))throw new InvalidDataException("external:texture-format-not-supported");if(!mat.HasProperty(name+"_ST")&&(mat.GetTextureOffset(name)!=Vector2.zero||mat.GetTextureScale(name)!=Vector2.one))throw new InvalidDataException("external:texture-transform-not-represented");}}}
   }
   if(RenderSettings.skybox||RenderSettings.ambientMode!=AmbientMode.Flat||RenderSettings.fog)throw new InvalidDataException("external:skybox-ambient-or-probes-not-supported");
   string scratch=Path.Combine("Library","SpatialExternalExport",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(scratch);GameObject clone=null,definitionObject=null;try{clone=UnityEngine.Object.Instantiate(definition.contentRoot.gameObject);clone.transform.localPosition=definition.contentRoot.localPosition;clone.transform.localRotation=definition.contentRoot.localRotation;clone.transform.localScale=definition.contentRoot.localScale;foreach(var component in clone.GetComponentsInChildren<MonoBehaviour>(true))if(program.Classes.ContainsKey(component.GetType().FullName))UnityEngine.Object.DestroyImmediate(component);definitionObject=new GameObject("External visual-only export definition");var visual=definitionObject.AddComponent<SceneDefinition>();visual.contentRoot=clone.transform;visual.templateId=definition.templateId;visual.displayName=definition.displayName;visual.authorFrame=definition.authorFrame;visual.licenseSource=definition.licenseSource;visual.licenseName=definition.licenseName;visual.editable=definition.editable;visual.reshare=definition.reshare;string assets=Path.Combine(scratch,"assets.spatial");ScenePackageExporter.Export(visual,assets,ExportMode.LocalValidation);return Wrap(assets,outputPath,definition.templateId,revision,definition.displayName,authorScript);}finally{if(clone)UnityEngine.Object.DestroyImmediate(clone);if(definitionObject)UnityEngine.Object.DestroyImmediate(definitionObject);Directory.Delete(scratch,true);}
  }
  public static string Wrap(string validatedDataPath,string outputPath,string workId,string revision,string name,byte[] scriptDefinition=null){
   if(File.Exists(outputPath))throw new IOException("external:destination-exists");var data=PackageValidator.Validate(validatedDataPath);var graph=(JArray)data.Scene["nodes"];var nodes=new JArray();foreach(JObject node in graph)nodes.Add(new JObject{{"id","n"+nodes.Count},{"parent",node["parent"].DeepClone()},{"components",new JArray(new JObject{{"kind","transform"},{"config",new JObject{{"position",node["position"].DeepClone()},{"rotation",node["rotation"].DeepClone()},{"scale",node["scale"].DeepClone()}}},{"fields",new JObject()},{"callbacks",new JArray()}})}});
   byte[] script=NativeScriptDefinition.Encode(new JObject{{"classes",new JArray()}},new JObject{{"frame",data.Scene["frame"].DeepClone()},{"resources",new JArray()},{"prefabs",new JArray()},{"nodes",nodes}}),assets=File.ReadAllBytes(validatedDataPath);if(scriptDefinition!=null){NativeScriptDefinition.Admit(scriptDefinition);script=(byte[])scriptDefinition.Clone();}var manifest=new JObject{{"format","spatial-external-native-wallpaper"},{"schema",5},{"sdk",SceneCommandCatalog.TargetSdk},{"command_abi",SceneCommandCatalog.Abi},{"catalog_digest",SceneCommandCatalog.Digest},{"work_id",workId},{"revision",revision},{"name",name},{"assets",new JObject{{"format","canonical-static-data-v1"},{"build_id",data.BuildId}}},{"files",new JObject{{"script.json",new JObject{{"size",script.Length},{"sha256",PackageValidator.Digest(script)}}},{"assets.spatial",new JObject{{"size",assets.Length},{"sha256",PackageValidator.Digest(assets)}}}}},{"license",data.Manifest["license"].DeepClone()},{"build_id",""}};manifest["build_id"]=PackageValidator.Identity(manifest);string target=Path.GetFullPath(outputPath);Directory.CreateDirectory(Path.GetDirectoryName(target));try{using(var stream=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create))foreach(var pair in new[]{new System.Collections.Generic.KeyValuePair<string,byte[]>("manifest.json",Encoding.UTF8.GetBytes(manifest.ToString(Formatting.None))),new System.Collections.Generic.KeyValuePair<string,byte[]>("script.json",script),new System.Collections.Generic.KeyValuePair<string,byte[]>("assets.spatial",assets)})using(var entry=zip.CreateEntry(pair.Key).Open())entry.Write(pair.Value,0,pair.Value.Length);NativeExternalPackage.Validate(target);return (string)manifest["build_id"];}catch{if(File.Exists(target))File.Delete(target);throw;}
  }
 }
}